function freshCrop(panel) {
  const starts = {
    hero: { zoom: 1, x: 0, y: -0.45 },
    scene: { zoom: 1.7, x: -0.68, y: 0.72 },
    detail: { zoom: 1.45, x: 0.62, y: -0.62 },
    atmosphere: { zoom: 1, x: 0, y: 0 },
  };
  return { ...starts[panel] };
}

